      "proposed_laureates": [
        "Fabiola Gianotti",
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central prediction of the Standard Model and was a defining achievement in particle physics.",
        "attribution": "The named leaders represent both ATLAS and CMS, whose independent results were essential; the discovery itself depended on thousands of collaborators.",
        "maturity": "The boson has been repeatedly observed and its properties measured, with results consistent so far with the Higgs mechanism.",
        "uncertainties": [
          "Recognition of four leaders may not capture the scale of the collaboration contributions or the complementary roles of the theory and experiment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turned atomic clocks into exceptionally precise tools for fundamental physics and metrology, with applications ranging from relativistic geodesy to tests of constants.",
        "attribution": "Katori and Ye independently pioneered complementary clock approaches and sustained the experimental advances that made the field practical.",
        "maturity": "The technique is highly mature, with optical clocks outperforming traditional standards and contributing to active redefinitions of timekeeping.",
        "uncertainties": [
          "The eventual impact on the international definition and dissemination of the second is still developing."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Max Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Correcting spherical aberration in transmission electron microscopes overcame a longstanding instrument limit and made atomic-scale structural imaging broadly accessible.",
        "attribution": "Rose supplied key optical concepts, while Urban and Haider were central to realizing and demonstrating practical corrected instruments.",
        "maturity": "The correction became a reliable, widely adopted technology, with lasting effects across materials science and microscopy.",
        "uncertainties": [
          "The division of credit between foundational theory, engineering realization, and subsequent commercialization is complex."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics established a controllable light–matter platform in which individual microwave photons and superconducting artificial atoms can be prepared, coupled, and measured.",
        "attribution": "Blais developed key theory, while Wallraff and Schoelkopf led decisive experimental demonstrations and platform development.",
        "maturity": "The field is experimentally mature and has become a foundation of superconducting quantum technology, though its ultimate computing impact remains unsettled.",
        "uncertainties": [
          "The long-term scientific significance of the resulting quantum technologies is not yet known.",
          "The platform was built through contributions from many groups beyond these pioneers."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Gregory N. Gol'tsman",
        "Roman Sobolewski",
        "Sae Woo Nam"
      ],
      "assessment": {
        "nobel_worthiness": "Superconducting nanowire single-photon detectors combine exceptional sensitivity, timing, and efficiency, enabling demanding experiments in quantum optics, astronomy, and communication.",
        "attribution": "The nominees represent early invention, development, and influential demonstrations, but the technology matured through substantial work by many groups.",
        "maturity": "These detectors are now established instruments with broad adoption, and their performance continues to improve.",
        "uncertainties": [
          "The historical division of credit for the invention and subsequent performance advances is not straightforward."
        ]
      }
    },
